+    GrokCaptureConfig(NameEntry nameEntry) {
+        String groupName = new String(nameEntry.name, nameEntry.nameP, nameEntry.nameEnd - nameEntry.nameP, StandardCharsets.UTF_8);
+        String[] parts = groupName.split(":");
